Una agencia reparte repartidores para visitar barrios; cada repartidor cubre varios. Siempre se contrata al que cubre más barrios aún sin visitar:

function contratar(barrios, repartidores) {
  const pendientes = new Set(barrios);
  const elegidos = [];
  while (pendientes.size > 0) {
    let mejor = null;
    let mejorCuenta = 0;
    for (const r of repartidores) {
      let cuenta = 0;
      for (const b of new Set(r.barrios)) if (pendientes.has(b)) cuenta += 1;
      if (cuenta > mejorCuenta) { mejorCuenta = cuenta; mejor = r; }
    }
    if (mejor === null) break;
    elegidos.push(mejor.nombre);
    for (const b of mejor.barrios) pendientes.delete(b);
  }
  return elegidos;
}
